export async function gate({ referenceDir, submissionDir }) {
  const fs = await import("node:fs");
  const path = await import("node:path");
  const { spawn } = await import("node:child_process");
  const crypto = await import("node:crypto");

  const token = crypto.randomBytes(32).toString("hex");
  const id = crypto.randomBytes(16).toString("hex");
  const resultFile = path.join(referenceDir, ".gr-" + id);
  const runnerFile = path.join(referenceDir, ".rn-" + id + ".mjs");
  const submissionFile = path.join(submissionDir, "answer.mjs");

  const runnerSrc = [
    "import fs from 'node:fs';",
    "import { pathToFileURL } from 'node:url';",
    "const writeOK = fs.writeFileSync.bind(fs);",
    "const JSONs = JSON.stringify.bind(JSON);",
    "const resultFile = " + JSON.stringify(resultFile) + ";",
    "const token = " + JSON.stringify(token) + ";",
    "const submissionFile = " + JSON.stringify(submissionFile) + ";",
    "function eq(a, b) { if (JSONs(a) !== JSONs(b)) throw new Error('fail'); }",
    "const mod = await import(pathToFileURL(submissionFile).href);",
    "const dedupeSorted = mod.dedupeSorted;",
    "if (typeof dedupeSorted !== 'function') process.exit(2);",
    "eq(dedupeSorted([]), []);",
    "eq(dedupeSorted([5]), [5]);",
    "eq(dedupeSorted([1, 2, 3]), [1, 2, 3]);",
    "eq(dedupeSorted([4, 4, 4, 4]), [4]);",
    "eq(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]);",
    "eq(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]);",
    "eq(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]);",
    "for (let trial = 0; trial < 20; trial++) {",
    "  const len = 1 + Math.floor(Math.random() * 10);",
    "  const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);",
    "  const expected = [...new Set(arr)];",
    "  eq(dedupeSorted(arr), expected);",
    "}",
    "writeOK(resultFile, token);",
  ].join("\n");

  fs.writeFileSync(runnerFile, runnerSrc);

  const outcome = await new Promise((resolve) => {
    let done = false;
    const finish = (v) => { if (!done) { done = true; resolve(v); } };
    const child = spawn(process.execPath, [runnerFile], {
      stdio: ["ignore", "ignore", "ignore"],
      env: { PATH: process.env.PATH || "/usr/bin:/bin" },
    });
    const t = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch {}
      finish({ code: -1 });
    }, 10000);
    child.on("close", (code) => { clearTimeout(t); finish({ code }); });
    child.on("error", () => { clearTimeout(t); finish({ code: -1 }); });
  });

  let accept = false;
  try {
    accept = fs.readFileSync(resultFile, "utf8") === token && outcome.code === 0;
  } catch {}
  try { fs.unlinkSync(resultFile); } catch {}
  try { fs.unlinkSync(runnerFile); } catch {}

  return accept
    ? { accept: true, reason: "all pinned tests passed and suite completed" }
    : { accept: false, reason: "pinned tests failed or suite did not complete" };
}

